// ===========================================================================
// 동결 type-trait 표(모듈·repacker와 일치) + 유틸
// ===========================================================================
struct TraitRow { const char * type; uint32_t bv; uint32_t bb; ggml_type gt; };
static const TraitRow kTraits[] = {
    { "F32",   1,   4,   GGML_TYPE_F32   },
    { "F16",   1,   2,   GGML_TYPE_F16   },
    { "MXFP4", 32,  17,  GGML_TYPE_MXFP4 },
    { "Q3_K",  256, 110, GGML_TYPE_Q3_K  },
    { "Q4_K",  256, 144, GGML_TYPE_Q4_K  },
    { "Q5_K",  256, 176, GGML_TYPE_Q5_K  },   // OPEN_ARCH B axis: all 8 rows of the engine's frozen
                                              // table are covered here too (--openarch-python-artifact
                                              // can receive a real Q5_K repack, so trait_of must not
                                              // hard-exit on it)
    { "Q6_K",  256, 210, GGML_TYPE_Q6_K  },
    { "Q8_0",  32,  34,  GGML_TYPE_Q8_0  },
};
static const TraitRow & trait_of(const std::string & t) {
    for (const auto & r : kTraits) if (t == r.type) return r;
    fprintf(stderr, "FATAL: unknown trait type %s\n", t.c_str()); exit(2);
}
static uint64_t ceil_to(uint64_t v, uint64_t a) { return (v + a - 1) / a * a; }
static uint64_t per_expert_slice(const std::string & type, const std::vector<int64_t> & dims) {
    const TraitRow & r = trait_of(type);
    uint64_t middle = 1;
    for (size_t i = 1; i + 1 < dims.size(); i++) middle *= (uint64_t)dims[i];
    return (uint64_t)(dims[0] / (int64_t)r.bv) * (uint64_t)r.bb * middle;
}
static uint8_t bin_hash(uint64_t off) {
    uint64_t x = off * 2654435761ull + 0x9E3779B97F4A7C15ull;
    x ^= x >> 29; x *= 0xBF58476D1CE4E5B9ull; x ^= x >> 32;
    return (uint8_t)(x & 0xFF);
}

// F1: 합성 expect 파일 재해시용 SHA-256(BCrypt) — 모듈의 sha256_file과 동일 알고리즘.
static std::string sha256_hex(const std::string & data) {
    unsigned char digest[32];
    BCryptHash(BCRYPT_SHA256_ALG_HANDLE, nullptr, 0, (PUCHAR)data.data(), (ULONG)data.size(), digest, sizeof(digest));
    static const char * hx = "0123456789abcdef";
    std::string o; o.reserve(64);
    for (int i = 0; i < 32; i++) { o.push_back(hx[digest[i] >> 4]); o.push_back(hx[digest[i] & 0xF]); }
    return o;
}
static std::string synth_expect_body(const std::string & profile_id, int32_t n_expert) {
    // 모듈은 이 파일을 재해시만 하고 필드는 검증하지 않는다(카탈로그 대조가 권위).
    json e = { {"expect_schema_version", "1.0"}, {"profile_id", profile_id}, {"arch", "synth"},
               {"n_expert", n_expert}, {"note", "moe-direct-selftest 합성 expect"} };
    return e.dump(1);
}

// ===========================================================================
// 합성 모델 명세 (v2)
// ===========================================================================
struct SynthSource { std::string path; uint64_t bytes; int64_t mtime; uint64_t data_start; uint32_t gguf_version; uint32_t alignment; };
struct SynthPart { std::string name; std::string source_tensor; int32_t source_index; std::string type; std::vector<int64_t> dims; bool is_host; };
struct SynthLayer { int32_t layer; std::vector<SynthPart> parts; };
struct SynthModel {
    std::string arch = "synth";
    int32_t n_expert = 8;
    int32_t n_expert_used = 2;
    int32_t n_layer = 4;
    int32_t n_layer_nextn = 0;        // ★부록A: NextN 예측층 수(live 디스크립터·execution 제외 경계)
    int32_t n_layer_dense_lead = 0;   // OPEN_ARCH B axis: leading_dense_block_count (input to the
                                      // deepseek2 layer-set formula)
    int32_t n_embd = 0;               // ★B2(R1 #5 ②): seal 시점 스냅샷 형상 확정용(0=미확정)
    float   f_norm_rms_eps = 1e-6f;
    std::vector<SynthLayer> layers;   // moe 층만(오름차순) — 매니페스트에 실리는 관리 대상 층
    std::vector<SynthSource> sources; // 최소 1개
};

struct CompPart { uint64_t part_offset; uint64_t part_bytes; };
struct CompLayer { int32_t layer; uint64_t payload; uint64_t stride; uint64_t record_base; std::vector<CompPart> parts; };
struct Computed { uint64_t A; uint64_t slot_stride_max; uint64_t bin_bytes; std::vector<CompLayer> layers; };

static Computed compute_layout(const SynthModel & m, uint64_t A) {
    Computed c; c.A = A; c.slot_stride_max = 0; uint64_t base = 0;
    for (const auto & L : m.layers) {
        CompLayer cl; cl.layer = L.layer; cl.record_base = base; uint64_t off = 0;
        for (const auto & p : L.parts) {
            uint64_t pb = per_expert_slice(p.type, p.dims);
            cl.parts.push_back({ off, pb }); off += pb;
        }
        cl.payload = off;
        cl.stride = ceil_to(cl.payload, A);
        if (cl.stride > c.slot_stride_max) c.slot_stride_max = cl.stride;
        base += (uint64_t)m.n_expert * cl.stride;
        c.layers.push_back(std::move(cl));
    }
    c.bin_bytes = base;
    return c;
}

static json build_manifest_json(const SynthModel & m, const Computed & c,
                                const std::string & ref_profile_id, const std::string & ref_expect_sha256,
                                const std::string & routed_scope = "") {
    json j;
    j["schema_version"] = "2.0";
    json moe_layers = json::array();
    for (const auto & L : m.layers) moe_layers.push_back(L.layer);
    j["model"] = { {"arch", m.arch}, {"n_layer", m.n_layer}, {"n_expert", m.n_expert},
                   {"n_expert_used", m.n_expert_used}, {"moe_layers", moe_layers} };
    // ★부록A: routed_scope 비어있으면 필드 생략(부재=all·기존 산출물 불변). 비면 그대로 기록.
    if (!routed_scope.empty()) j["model"]["routed_scope"] = routed_scope;
    json sources = json::array();
    for (size_t i = 0; i < m.sources.size(); i++) {
        const auto & s = m.sources[i];
        sources.push_back({ {"index", (int32_t)i}, {"path", s.path}, {"bytes", s.bytes},
                            {"mtime", (double)s.mtime}, {"gguf_version", s.gguf_version},
                            {"alignment", s.alignment}, {"data_start", s.data_start} });
    }
    j["sources"] = sources;

    json layers = json::array();
    std::set<std::string> used_types;
    json source_tensors = json::array();
    for (size_t li = 0; li < m.layers.size(); li++) {
        const auto & L = m.layers[li];
        const auto & cl = c.layers[li];
        json parts = json::array();
        for (size_t pi = 0; pi < L.parts.size(); pi++) {
            const auto & p = L.parts[pi];
            used_types.insert(p.type);
            json dims = json::array(); for (auto d : p.dims) dims.push_back(d);
            parts.push_back({ {"name", p.name}, {"source_tensor", p.source_tensor}, {"source_index", p.source_index},
                              {"type", p.type}, {"dims", dims}, {"expert_axis", (int32_t)p.dims.size() - 1},
                              {"part_offset", cl.parts[pi].part_offset}, {"part_bytes", cl.parts[pi].part_bytes} });
            json sdims = json::array(); for (auto d : p.dims) sdims.push_back(d);
            source_tensors.push_back({ {"name", p.source_tensor}, {"source_index", p.source_index}, {"abs_offset", 0},
                                       {"bytes", cl.parts[pi].part_bytes * (uint64_t)m.n_expert}, {"type", p.type}, {"dims", sdims} });
        }
        layers.push_back({ {"layer", L.layer}, {"payload_bytes", cl.payload}, {"stride_bytes", cl.stride},
                           {"record_base", cl.record_base}, {"parts", parts} });
    }
    j["layout"] = { {"align_bytes", c.A},
                    {"align_query", {{"method", "IOCTL_STORAGE_QUERY_PROPERTY"}, {"logical", 512}, {"physical", 4096}, {"fallback_reason", nullptr}}},
                    {"slot_stride_max", c.slot_stride_max}, {"layers", layers} };

    json records = json::array();
    for (size_t li = 0; li < m.layers.size(); li++) {
        const auto & cl = c.layers[li];
        for (int32_t e = 0; e < m.n_expert; e++)
            records.push_back({ {"layer", cl.layer}, {"expert", e}, {"offset", cl.record_base + (uint64_t)e * cl.stride}, {"payload_bytes", cl.payload} });
    }
    j["records"] = records;
    j["source_tensors"] = source_tensors;

    json quant_traits = json::object();
    for (const auto & t : used_types) { const TraitRow & r = trait_of(t); quant_traits[t] = { {"block_values", r.bv}, {"block_bytes", r.bb} }; }
    j["quant_traits"] = quant_traits;

    uint64_t ept = 0; for (const auto & cl : c.layers) ept += (uint64_t)m.n_expert * cl.payload;
    j["totals"] = { {"expert_payload_total", ept}, {"bin_file_bytes", c.bin_bytes}, {"n_records", (int64_t)m.layers.size() * m.n_expert} };
    j["reference_lock"] = { {"profile_id", ref_profile_id}, {"expect_sha256", ref_expect_sha256} };
    j["tool"] = { {"version", "2.0.0"}, {"ts", "2026-07-23T00:00:00+00:00"}, {"cmdline", "selftest"} };
    return j;
}

// verify_report.json(JSONL) 합성 — 실 프로듀서 스키마와 동형(10키: pairs_total·pairs_pass·
// expected_pairs·pass·failures·padding_failures·problems·reference_lock·manifest_sha256·checked_at.
// 권위=bench/repack/repack_experts.py verify_repack() 반환 dict, 실물 대조=bench_results/laptop/
// repack_35b_verify_report.json). 모듈이 이 레코드를 release 게이트로 소비한다.
// ★네거티브 주입 훅 = verify PASS 소비 게이트(H7~H10) 전용. 픽스처는 유계(pairs=8 고정·
//   failures 최대 1건 — 무한 누적 금지).
struct VerifyReportOverride {
    int  pass_mode        = 0;      // 0=pass:true · 1=pass:false · 2=pass 키 생략
    bool pairs_mismatch   = false;  // pairs_pass != pairs_total(등식 파괴)
    bool nonempty_failures = false; // failures 배열 1건(비공집합)
    // ★cache key 결속(⑦): 0=실 manifest.json 바이트 해시 · 1=키 생략(구 스키마) · 2=불일치 값
    int  manifest_sha_mode = 0;
};
static void write_verify_report(const std::wstring & path, const std::string & profile_id, const std::string & sha,
                                const std::string & manifest_sha,
                                const VerifyReportOverride & ov = VerifyReportOverride()) {
    const int64_t PAIRS = 8;  // 합성 고정치(유계) — 실 재팩 수치와 무관, 등식 성립만이 의미
    json vr = json::object();
    vr["pairs_total"]    = PAIRS;
    vr["pairs_pass"]     = ov.pairs_mismatch ? (PAIRS - 1) : PAIRS;
    vr["expected_pairs"] = PAIRS;
    if      (ov.pass_mode == 0) vr["pass"] = true;
    else if (ov.pass_mode == 1) vr["pass"] = false;   // pass_mode==2 → 키 자체 생략
    vr["failures"] = json::array();
    if (ov.nonempty_failures) {
        vr["failures"].push_back({ {"layer", 0}, {"expert", 0}, {"part", "synth"},
                                   {"src_offset", 0}, {"out_offset", 0} });
    }
    vr["padding_failures"] = json::array();
    vr["problems"]         = json::array();
    vr["reference_lock"]   = { {"profile_id", profile_id}, {"expect_sha256", sha} };
    if      (ov.manifest_sha_mode == 0) vr["manifest_sha256"] = manifest_sha;
    else if (ov.manifest_sha_mode == 2) vr["manifest_sha256"] = std::string(64, 'e'); // 유효 hex·값 불일치
    // manifest_sha_mode==1 → 키 자체 생략(구 스키마 report)
    vr["checked_at"]       = "2026-07-24T00:00:00+00:00";
    std::ofstream ofs(path, std::ios::binary | std::ios::trunc);
    ofs << vr.dump() << "\n";
}

// ★양성 회귀: bench_results/laptop/repack_35b_verify_report.json(노트북 35B 재팩 **실물** 레코드)을
// 그대로 옮기고 reference_lock 만 합성값으로 치환한다(그 필드는 manifest 와 대조되므로 합성 필수).
// 합성 스키마(write_verify_report)가 실 프로듀서 산출물과 어긋나면 이 케이스에서 잡힌다.
// ★manifest_sha256 은 재팩 시점의 실 manifest 바이트 해시라 실물 그대로 옮길 수 없다(합성 manifest
// 와 결속돼야 함) — reference_lock 과 같은 이유로 합성값 치환. 나머지 키·값·순서는 실물 그대로.
static void write_verify_report_real_record(const std::wstring & path, const std::string & profile_id, const std::string & sha,
                                            const std::string & manifest_sha) {
    std::string s = "{\"pairs_total\": 30720, \"pairs_pass\": 30720, \"expected_pairs\": 30720, "
                    "\"pass\": true, \"failures\": [], \"padding_failures\": [], \"problems\": [], "
                    "\"reference_lock\": {\"profile_id\": \"" + profile_id + "\", \"expect_sha256\": \"" + sha + "\"}, "
                    "\"manifest_sha256\": \"" + manifest_sha + "\", "
                    "\"checked_at\": \"2026-07-28T14:15:53.627601+00:00\"}";
    std::ofstream ofs(path, std::ios::binary | std::ios::trunc);
    ofs << s << "\n";
}

static void write_manifest(const std::wstring & path, const json & j) {
    std::ofstream ofs(path, std::ios::binary | std::ios::trunc);
    ofs << j.dump(1);
}
// ★디스크에 쓰인 manifest.json **파일 바이트**의 SHA-256(= 프로듀서 verify 가 report 에 싣는 값).
// 파일을 되읽어 해시한다 — dump 문자열 재구성이 아니라 실제 바이트여야 소비자 대조와 등가.
static std::string sha256_file_hex(const std::wstring & path) {
    std::ifstream ifs(path, std::ios::binary);
    std::string data((std::istreambuf_iterator<char>(ifs)), std::istreambuf_iterator<char>());
    return sha256_hex(data);
}
// content_override_bytes<0: 정상 크기(bin_bytes). >=0: 그 크기만 쓴다(크기 불일치 네거티브용).
static void write_bin_hash(const std::wstring & path, const Computed & c, int64_t content_override = -1) {
    HANDLE h = CreateFileW(path.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (h == INVALID_HANDLE_VALUE) { fprintf(stderr, "write_bin_hash CreateFileW 실패 err=%lu\n", (unsigned long)GetLastError()); return; }
    uint64_t target = content_override >= 0 ? (uint64_t)content_override : c.bin_bytes;
    std::vector<uint8_t> buf(1 << 20);
    uint64_t off = 0;
    while (off < target) {
        uint64_t chunk = (uint64_t)buf.size(); if (chunk > target - off) chunk = target - off;
        for (uint64_t i = 0; i < chunk; i++) buf[(size_t)i] = bin_hash(off + i);
        DWORD written = 0; WriteFile(h, buf.data(), (DWORD)chunk, &written, nullptr);
        off += written; if (written == 0) break;
    }
    CloseHandle(h);
}

// ===========================================================================
// OPEN_ARCH B axis (OPENARCH_B_SPEC_DRAFT v0.2) - template fixture support.
//
// INDEPENDENT IMPLEMENTATION on purpose: the row assembly, sort and digest below do NOT reuse the
// engine's closure arithmetic (ggml-moe-direct.cpp) - they are written again here. A positive case
// only passes when both implementations produce the same digest, so if either side changes the wire
// format (separator, sort, type spelling, dims serialisation) they diverge immediately.
// The three-way comparison against the producer (Python) is the Gate C runner's job
// (--openarch-python-artifact).
// ===========================================================================

// row = "<tensor-name>\t<type>\t<d0>,<d1>,..\t<layer>\t<scope>\n"
static std::string tpl_row(const std::string & name, const std::string & type,
                           const std::vector<int64_t> & dims, int32_t layer, const std::string & scope) {
    std::string s = name; s += '\t'; s += type; s += '\t';
    for (size_t i = 0; i < dims.size(); i++) { if (i) s += ','; s += std::to_string((long long)dims[i]); }
    s += '\t'; s += std::to_string(layer); s += '\t'; s += scope; s += '\n';
    return s;
}
// sha256( "MOE-INVENTORY-V1\n" + "".join(sorted(rows)) )
static std::string tpl_inventory_digest(std::vector<std::string> rows) {
    std::sort(rows.begin(), rows.end());
    std::string payload = "MOE-INVENTORY-V1\n";
    for (const auto & r : rows) payload += r;
    return sha256_hex(payload);
}

// digest input mutations (the negative axis - each field is exercised separately to show it really
// is bound into the digest).
enum class TplRowMut { NONE, DROP, ADD, TYPE, DIMS, LAYER, SCOPE };

// ===========================================================================
// 합성 텐서(ggml no_alloc ctx + VirtualAlloc backing) + 등록
// ===========================================================================
struct Fixture {
    SynthModel model;
    Computed comp;
    std::wstring dir;
    ggml_context * ctx = nullptr;
    std::vector<void *> blocks;
    std::vector<std::pair<std::string, ggml_tensor *>> tensors; // source_tensor -> tensor
    // F1 reference_lock 결속(합성 expect+카탈로그 주입).
    std::string ref_profile_id = "synth";
    std::string ref_expect_sha256;      // build()에서 확정
    std::string manifest_file_sha256;   // ★build()에서 확정 — 디스크 manifest.json 바이트 해시(⑦ 결속 키)
    // 네거티브 주입 훅(0=정상)
    std::string vr_pid_override, vr_sha_override; // verify_report에 다른 값 쓰기
    std::string manifest_sha_override;            // manifest.reference_lock.expect_sha256 오염
    VerifyReportOverride vr_gate;                 // ★verify PASS 소비 게이트 네거티브(H7~H10)
    bool write_partial_marker = false;            // ★experts.bin.partial 잔존(중단 재팩) 유도(H11)
    bool vr_real_record = false;                  // ★실 프로듀서 레코드 그대로 쓰기(H0b 양성)
    bool tamper_expect_file = false;              // expect 파일 재해시 불일치 유도
    // ★부록A dual-scope 훅
    std::string routed_scope;                     // "" = manifest 미기록(부재=all) · else "all"/"execution"/미지값
    std::vector<SynthLayer> extra_live_layers;    // live-only(등록되나 manifest/bin 미포함 — execution 제외 대상)

    // OPEN_ARCH B axis template hooks (with tpl_mode=false the existing model-pin path is byte for
    // byte unchanged).
    bool        tpl_mode = false;
    std::string tpl_template_id;                  // template_id in the lock/expect (e.g. "gpt-oss")
    std::string tpl_template_version = "1";       // version in the lock/expect
    std::string tpl_lock_id;                      // "" = assemble "arch-template:<id>@<ver>"
    std::string tpl_expect_template_id;           // "" = tpl_template_id (override for 3-way mismatch negatives)
    std::string tpl_expect_template_version;      // "" = tpl_template_version
    std::string tpl_expect_derived_from;          // "" = "<id>@<ver>"
    std::string tpl_expect_schema_version = "1.0";
    bool        tpl_omit_schema_version = false;  // drop the key itself (13-key violation + absence negative)
    std::string tpl_expect_scope;                 // "" = normalize(routed_scope)
    std::string tpl_inventory_override;           // "" = computed from the row assembly below
    bool        tpl_extra_key = false;            // 14 keys (key added)
    bool        tpl_omit_expect_file = false;     // do not write derived.expect.json (file absent)
    bool        tpl_tamper_expect_file = false;   // append one byte after writing (re-hash mismatch)
    TplRowMut   tpl_row_mut = TplRowMut::NONE;    // per-axis mutation of the digest input

    // Rows are assembled from the MANAGED (manifest) layers - in a positive fixture that set is
    // exactly the formula set.
    std::vector<std::string> tpl_rows() const {
        const std::string scope = routed_scope.empty() ? std::string("all") : routed_scope;
        std::vector<std::string> rows;
        for (const auto & L : model.layers) {
            for (const auto & p : L.parts) {
                rows.push_back(tpl_row(p.source_tensor, p.type, p.dims, L.layer, scope));
            }
        }
        if (rows.empty()) return rows;
        switch (tpl_row_mut) {
            case TplRowMut::NONE:  break;
            case TplRowMut::DROP:  rows.pop_back(); break;
            case TplRowMut::ADD:
                rows.push_back(tpl_row("blk.999.ffn_gate_exps.weight", "F32", { 4, model.n_expert }, 999, scope));
                break;
            case TplRowMut::TYPE: {
                const auto & L = model.layers.front(); const auto & p = L.parts.front();
                rows[0] = tpl_row(p.source_tensor, p.type == "F32" ? "F16" : "F32", p.dims, L.layer, scope);
                break; }
            case TplRowMut::DIMS: {
                const auto & L = model.layers.front(); const auto & p = L.parts.front();
                std::vector<int64_t> d = p.dims; d[0] += 1;
                rows[0] = tpl_row(p.source_tensor, p.type, d, L.layer, scope);
                break; }
            case TplRowMut::LAYER: {
                const auto & L = model.layers.front(); const auto & p = L.parts.front();
                rows[0] = tpl_row(p.source_tensor, p.type, p.dims, L.layer + 100, scope);
                break; }
            case TplRowMut::SCOPE: {
                const auto & L = model.layers.front(); const auto & p = L.parts.front();
                rows[0] = tpl_row(p.source_tensor, p.type, p.dims, L.layer,
                                  scope == "execution" ? "all" : "execution");
                break; }
        }
        return rows;
    }

    // The derived expect body of the frozen 13-key schema (after the negative hooks are applied).
    std::string tpl_expect_body() const {
        const std::string tid = tpl_expect_template_id.empty() ? tpl_template_id : tpl_expect_template_id;
        const std::string tver = tpl_expect_template_version.empty() ? tpl_template_version : tpl_expect_template_version;
        const std::string dfrom = tpl_expect_derived_from.empty() ? (tpl_template_id + "@" + tpl_template_version)
                                                                  : tpl_expect_derived_from;
        const std::string scope = tpl_expect_scope.empty()
            ? (routed_scope.empty() ? std::string("all") : routed_scope) : tpl_expect_scope;
        int32_t routed = 0;
        uint64_t bytes_total = 0;
        for (size_t li = 0; li < model.layers.size(); li++) {
            routed += (int32_t)model.layers[li].parts.size();
            bytes_total += (uint64_t)model.n_expert * comp.layers[li].payload;
        }
        json e = json::object();
        if (!tpl_omit_schema_version) e["expect_schema_version"] = tpl_expect_schema_version;
        e["derived_from"]       = dfrom;
        e["template_id"]        = tid;
        e["template_version"]   = tver;
        e["inventory_sha256"]   = tpl_inventory_override.empty() ? tpl_inventory_digest(tpl_rows())
                                                                 : tpl_inventory_override;
        e["routed_scope"]       = scope;
        e["arch"]               = model.arch;
        e["n_layer"]            = model.n_layer;
        e["n_expert"]           = model.n_expert;
        e["n_expert_used"]      = model.n_expert_used;
        e["routed_tensors"]     = routed;
        e["expert_bytes_total"] = bytes_total;
        json srcs = json::array();
        for (const auto & s : model.sources) srcs.push_back({ {"file_bytes", s.bytes}, {"data_start", s.data_start} });
        e["sources"]            = srcs;
        if (tpl_extra_key) e["unexpected_extra_key"] = 1;
        return e.dump(1) + "\n";
    }

    ~Fixture() {
        ggml_moe_direct_reset_for_test();
        for (void * b : blocks) if (b) VirtualFree(b, 0, MEM_RELEASE);
        if (ctx) ggml_free(ctx);
    }

    ggml_tensor * find(const std::string & name) {
        for (auto & kv : tensors) if (kv.first == name) return kv.second;
        return nullptr;
    }

    // 텐서 생성 + 등록. bin/manifest 도 쓴다.
    void build() {
        int n_tensors = 0;
        for (auto & L : model.layers) n_tensors += (int)L.parts.size();
        for (auto & L : extra_live_layers) n_tensors += (int)L.parts.size();
        // +8 슬랙: 일부 케이스가 build() 후 ctx에 여분 텐서를 추가 등록(예: L_all 초과 네거티브).
        ggml_init_params p{}; p.mem_size = (size_t)(n_tensors + 8) * ggml_tensor_overhead() + 4096; p.no_alloc = true;
        ctx = ggml_init(p);

        // model.layers = manifest/bin 관리 대상, extra_live_layers = live-only(등록되나 제외 대상).
        // 둘 다 텐서 생성·등록(등록은 전수 유지 — seal이 scope로 선별).
        auto emit_layers = [&](std::vector<SynthLayer> & layers) {
            for (auto & L : layers) {
                for (auto & part : L.parts) {
                    const TraitRow & r = trait_of(part.type);
                    int64_t ne[GGML_MAX_DIMS] = {1,1,1,1};
                    for (size_t i = 0; i < part.dims.size(); i++) ne[i] = part.dims[i];
                    ggml_tensor * t = ggml_new_tensor(ctx, r.gt, (int)part.dims.size(), ne);
                    ggml_set_name(t, part.source_tensor.c_str());
                    size_t nb = ggml_nbytes(t);
                    size_t alloc = (size_t)ceil_to(nb, 65536);
                    void * blk = VirtualAlloc(nullptr, alloc, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
                    blocks.push_back(blk);
                    t->data = blk;
                    tensors.push_back({ part.source_tensor, t });
                    ggml_moe_direct_register(t, part.source_tensor.c_str(), part.is_host ? 1 : 0);
                }
            }
        };
        emit_layers(model.layers);
        emit_layers(extra_live_layers);
        if (tpl_mode) {
            // OPEN_ARCH B axis: lock = "arch-template:<id>@<ver>" and expect =
            // <dir>\derived.expect.json (the bundle expects_dir is unused by the template branch).
            ref_profile_id = tpl_lock_id.empty()
                ? ("arch-template:" + tpl_template_id + "@" + tpl_template_version) : tpl_lock_id;
            const std::string body = tpl_expect_body();
            ref_expect_sha256 = sha256_hex(body);
            if (!tpl_omit_expect_file) {
                const std::string on_disk = tpl_tamper_expect_file ? (body + " ") : body;
                std::ofstream ofs(dir + L"\\derived.expect.json", std::ios::binary | std::ios::trunc);
                ofs << on_disk;
            }
        } else {
        // F1: 합성 expect 파일 작성(<dir>/<profile_id>.expect.json) + sha256 확정.
        std::string expect_body = synth_expect_body(ref_profile_id, model.n_expert);
        ref_expect_sha256 = sha256_hex(expect_body);
        {
            std::string body_on_disk = tamper_expect_file ? (expect_body + "\n// tampered") : expect_body;
            std::ofstream ofs(dir + L"\\" + utf8_to_wide(ref_profile_id) + L".expect.json", std::ios::binary | std::ios::trunc);
            ofs << body_on_disk;
        }
        }
        std::string manifest_sha = manifest_sha_override.empty() ? ref_expect_sha256 : manifest_sha_override;
        json m = build_manifest_json(model, comp, ref_profile_id, manifest_sha, routed_scope);
        write_manifest(dir + L"\\manifest.json", m);
        write_bin_hash(dir + L"\\experts.bin", comp);
        // ★cache key 결속: report 의 manifest_sha256 = 방금 쓴 manifest.json 실 파일 바이트 해시.
        manifest_file_sha256 = sha256_file_hex(dir + L"\\manifest.json");
        // verify_report.json — 마지막 레코드 reference_lock(정상=manifest와 동일).
        std::string vr_pid = vr_pid_override.empty() ? ref_profile_id : vr_pid_override;
        std::string vr_sha = vr_sha_override.empty() ? manifest_sha : vr_sha_override;
        if (vr_real_record) write_verify_report_real_record(dir + L"\\verify_report.json", vr_pid, vr_sha, manifest_file_sha256);
        else                write_verify_report(dir + L"\\verify_report.json", vr_pid, vr_sha, manifest_file_sha256, vr_gate);
        // ★재팩 미완료 표식(프로듀서는 verify pass 시에만 제거) — 0바이트 유계 파일.
        if (write_partial_marker) {
            std::ofstream ofs(dir + L"\\experts.bin.partial", std::ios::binary | std::ios::trunc);
        }
    }

    ggml_moe_direct_model model_desc(std::vector<int32_t> & moe_layers_out) {
        // live moe_layers = manifest 관리 층 + live-only(extra) 층. 오름차순 정렬(라이브 디스크립터 권위).
        for (auto & L : model.layers) moe_layers_out.push_back(L.layer);
        for (auto & L : extra_live_layers) moe_layers_out.push_back(L.layer);
        std::sort(moe_layers_out.begin(), moe_layers_out.end());
        ggml_moe_direct_model md{};
        md.arch = model.arch.c_str();
        md.n_layer = model.n_layer;
        md.n_expert = model.n_expert;
        md.n_expert_used = model.n_expert_used;
        md.moe_layers = moe_layers_out.data();
        md.n_moe_layers = (int32_t)moe_layers_out.size();
        md.n_layer_nextn = model.n_layer_nextn;
        md.n_embd        = model.n_embd;            // ★B2(R1 #5 ②)
        md.f_norm_rms_eps= model.f_norm_rms_eps;
        md.n_layer_dense_lead = model.n_layer_dense_lead;   // OPEN_ARCH B axis (section 2-6 descriptor extension)
        return md;
    }
    std::vector<ggml_moe_direct_source> source_descs(std::vector<std::string> & path_store) {
        for (auto & s : model.sources) path_store.push_back(s.path);
        std::vector<ggml_moe_direct_source> v;
        for (size_t i = 0; i < model.sources.size(); i++) {
            ggml_moe_direct_source d{};
            d.path = path_store[i].c_str(); d.bytes = model.sources[i].bytes; d.mtime_epoch = model.sources[i].mtime;
            d.data_start = model.sources[i].data_start; d.gguf_version = model.sources[i].gguf_version; d.alignment = model.sources[i].alignment;
            v.push_back(d);
        }
        return v;
    }

    // expects_dir/catalog 를 명시하지 않으면 정상 결속(dir 자체가 expects_dir, 카탈로그=합성 sha).
    // ★부록A: 테스트 카탈로그 scope = normalize(routed_scope)("" → "all"). manifest routed_scope 와 대조됨.
    int seal(uint64_t budget_bytes, uint32_t touch_abort) {
        std::string cat_scope = routed_scope.empty() ? std::string("all") : routed_scope;
        return seal_ex(budget_bytes, touch_abort, wide_to_utf8(dir), ref_profile_id.c_str(), ref_expect_sha256.c_str(), cat_scope);
    }
    // OPEN_ARCH B axis template seal - it uses neither expects_dir nor a test catalog injection.
    //   Approval comes from the REAL 3-row ARCH_TEMPLATE_CATALOG, binding from <dir>\derived.expect.json.
    int seal_tpl(uint64_t budget_bytes, uint32_t touch_abort) {
        std::vector<int32_t> ml; std::vector<std::string> paths;
        ggml_moe_direct_model md = model_desc(ml);
        std::vector<ggml_moe_direct_source> srcs = source_descs(paths);
        return ggml_moe_direct_seal_for_test(wide_to_utf8(dir).c_str(), &md, srcs.data(), (int32_t)srcs.size(),
                                             budget_bytes, touch_abort, "", nullptr, nullptr, nullptr);
    }
    int seal_ex(uint64_t budget_bytes, uint32_t touch_abort,
                const std::string & expects_dir, const char * test_pid, const char * test_digest,
                const std::string & test_scope = "all") {
        std::vector<int32_t> ml; std::vector<std::string> paths;
        ggml_moe_direct_model md = model_desc(ml);
        std::vector<ggml_moe_direct_source> srcs = source_descs(paths);
        return ggml_moe_direct_seal_for_test(wide_to_utf8(dir).c_str(), &md, srcs.data(), (int32_t)srcs.size(),
                                             budget_bytes, touch_abort, expects_dir.c_str(), test_pid, test_digest, test_scope.c_str());
    }
};

// 기본 단일 소스.
static SynthSource default_source(int idx = 0) {
    SynthSource s;
    s.path = std::string("C:\\fake\\shard") + std::to_string(idx) + ".gguf";
    s.bytes = 123456789ull + idx; s.mtime = 1700000000 + idx; s.data_start = 4096; s.gguf_version = 3; s.alignment = 32;
    return s;
}

// gate/up/down separate weight 3파트(+옵션 bias)로 층을 구성.
static SynthLayer make_separate_layer(int32_t layer, int32_t n_expert, const std::string & wtype, bool with_bias, bool host = true, int src = 0) {
    SynthLayer L; L.layer = layer;
    const char * wn[3] = { "gate", "up", "down" };
    for (int i = 0; i < 3; i++) {
        SynthPart p; p.name = std::string(wn[i]) + ".weight";
        p.source_tensor = "blk." + std::to_string(layer) + ".ffn_" + wn[i] + "_exps.weight";
        p.source_index = src; p.type = wtype; p.dims = { 32, n_expert }; p.is_host = host; // MXFP4 ne0=32
        L.parts.push_back(p);
    }
    if (with_bias) for (int i = 0; i < 3; i++) {
        SynthPart p; p.name = std::string(wn[i]) + ".bias";
        p.source_tensor = "blk." + std::to_string(layer) + ".ffn_" + wn[i] + "_exps.bias";
        p.source_index = src; p.type = "F32"; p.dims = { 4, n_expert }; p.is_host = host;
        L.parts.push_back(p);
    }
    return L;
}
// fused gate_up + down (bias 무), 타입 지정(층별 stride 상이 행사용).
static SynthLayer make_fused_layer(int32_t layer, int32_t n_expert, const std::string & type, int64_t mid) {
    SynthLayer L; L.layer = layer;
    SynthPart gu; gu.name = "gate_up.weight"; gu.source_tensor = "blk." + std::to_string(layer) + ".ffn_gate_up_exps.weight";
    gu.source_index = 0; gu.type = type; gu.dims = { 256, mid, n_expert }; gu.is_host = true; // Q*_K ne0=256
    SynthPart dn; dn.name = "down.weight"; dn.source_tensor = "blk." + std::to_string(layer) + ".ffn_down_exps.weight";
    dn.source_index = 0; dn.type = type; dn.dims = { 256, mid, n_expert }; dn.is_host = true;
    L.parts = { gu, dn };
    return L;
}

// ===========================================================================
// 공용: ptr 데이터 검증(슬롯이 bin 레코드 사본이므로 ptr[j]==bin_hash(record_off+part_off+j))
// ===========================================================================
static bool verify_ptr_bytes(Fixture & fx, const std::string & tname, int32_t mlpos, int32_t part_idx, int32_t expert, int check_n = 24) {
    ggml_tensor * t = fx.find(tname);
    if (!t) return false;
    const CompLayer & cl = fx.comp.layers[(size_t)mlpos];
    uint64_t record_off = cl.record_base + (uint64_t)expert * cl.stride;
    uint64_t part_off = cl.parts[(size_t)part_idx].part_offset;
    uint64_t pbytes = cl.parts[(size_t)part_idx].part_bytes;
    const uint8_t * ptr = (const uint8_t *)ggml_moe_direct_ptr(t, expert);
    if (!ptr) return false;
    int lim = (int)std::min<uint64_t>((uint64_t)check_n, pbytes);
    for (int j = 0; j < lim; j++) if (ptr[j] != bin_hash(record_off + part_off + (uint64_t)j)) return false;
    return true;
}

// ===========================================================================
// 케이스 A: 리더 계약(정상 읽기·OVERLAPPED 완료 분기·정렬 강제)  [v1 승계]
// ===========================================================================
static void test_reader_contract() {
    section("A. 리더 계약(v2) — 정상 직독·ptr 바이트 일치·OVERLAPPED 완료 분기");
    Fixture fx; fx.dir = make_case_dir("reader");
    fx.model.arch = "synth"; fx.model.n_expert = 8; fx.model.n_expert_used = 2; fx.model.n_layer = 2;
    fx.model.sources = { default_source() };
    fx.model.layers = { make_separate_layer(0, 8, "MXFP4", true), make_separate_layer(1, 8, "MXFP4", true) };
    fx.comp = compute_layout(fx.model, 4096);
    fx.build();
    int rc = fx.seal((uint64_t)8 * fx.comp.slot_stride_max, 64); // 8슬롯>=n_expert 8
    if (!check(rc == 0, "A1. seal 성공(separate 3w+3b·2층·MXFP4)")) return;

    ggml_tensor * gate0 = fx.find("blk.0.ffn_gate_exps.weight");
    int32_t ids[3] = { 0, 3, 7 };
    int arc = ggml_moe_direct_acquire(gate0, ids, 3, 1);
    check(arc == 0, "A2. acquire(experts 0,3,7) 성공");
    bool ptr_ok = verify_ptr_bytes(fx, "blk.0.ffn_gate_exps.weight", 0, 0, 0) &&
                  verify_ptr_bytes(fx, "blk.0.ffn_gate_exps.weight", 0, 0, 7);
    // down.weight(part 2)·gate.bias(part 3)도 같은 레코드에서 파트 오프셋 분리 검증
    ptr_ok = ptr_ok && verify_ptr_bytes(fx, "blk.0.ffn_down_exps.weight", 0, 2, 3);
    ptr_ok = ptr_ok && verify_ptr_bytes(fx, "blk.0.ffn_gate_exps.bias", 0, 3, 3);
    check(ptr_ok, "A3. ★ptr(tensor,e)=슬롯+part_offset 바이트가 bin 레코드 파트와 정확 일치");
    ggml_moe_direct_release(gate0, ids, 3);

    uint64_t imm = 0, pend = 0;
    ggml_moe_direct_test_read_stats(&imm, &pend);
    check(imm + pend >= 3, "A4. OVERLAPPED 완료 분기 카운터 합 >= 미스 수(즉시성공/PENDING 관측)");
}

// ===========================================================================
// 케이스 B: 등록 불변식(L_all==M_all·비host attestation·크기 불일치)  [v1 승계]
// ===========================================================================
static void test_registration_invariants() {
    section("B. 등록 불변식 — L_all==M_all 양방향·attestation all/host/nonhost·bin 크기");
    // B1: L_all 초과(manifest에 없는 텐서 등록) → seal 실패
    {
        Fixture fx; fx.dir = make_case_dir("reg_extra");
        fx.model.n_expert = 8; fx.model.n_expert_used = 2; fx.model.n_layer = 1;
        fx.model.sources = { default_source() };
        fx.model.layers = { make_separate_layer(0, 8, "MXFP4", false) };
        fx.comp = compute_layout(fx.model, 4096);
        fx.build();
        // manifest에 없는 여분 텐서를 추가 등록(L_all > M_all)
        int64_t ne[2] = { 32, 8 };
        ggml_tensor * extra = ggml_new_tensor(fx.ctx, GGML_TYPE_MXFP4, 2, ne);
        void * blk = VirtualAlloc(nullptr, 65536, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE); fx.blocks.push_back(blk); extra->data = blk;
        ggml_moe_direct_register(extra, "blk.0.ffn_gate_exps.bias", 1); // manifest엔 bias 없음
        int rc = fx.seal((uint64_t)8 * fx.comp.slot_stride_max, 64);
        check(rc < 0, "B1. L_all 초과(manifest 없는 텐서 등록) → seal 실패(fail-closed)");
    }
    // B2: 정상 + 비host 섞임 → attestation all/host/nonhost 분리
    {
        Fixture fx; fx.dir = make_case_dir("reg_attest");
        fx.model.n_expert = 8; fx.model.n_expert_used = 2; fx.model.n_layer = 1;
        fx.model.sources = { default_source() };
        SynthLayer L = make_separate_layer(0, 8, "MXFP4", false);
        L.parts[2].is_host = false; // down.weight 를 비host로
        fx.model.layers = { L };
        fx.comp = compute_layout(fx.model, 4096);
        fx.build();
        int rc = fx.seal((uint64_t)8 * fx.comp.slot_stride_max, 64);
        if (check(rc == 0, "B2. seal 성공(host 2 + nonhost 1)")) {
            int all = 0, host = 0, nonhost = 0, ns = 0, nsr = 0;
            ggml_moe_direct_attestation(&all, &host, &nonhost, &ns, &nsr);
            check(all == 3 && host == 2 && nonhost == 1, "B3. ★attestation all=3 host=2 nonhost=1(3집합 분리)");
            check(ns >= 8 && nsr == 8, "B4. attestation 슬롯 실제>=필요·필요==n_expert(8)");
        }
    }
    // B3: bin 실크기 불일치 → seal 실패
    {
        Fixture fx; fx.dir = make_case_dir("reg_binsize");
        fx.model.n_expert = 8; fx.model.n_expert_used = 2; fx.model.n_layer = 1;
        fx.model.sources = { default_source() };
        fx.model.layers = { make_separate_layer(0, 8, "MXFP4", false) };
        fx.comp = compute_layout(fx.model, 4096);
        fx.build();
        write_bin_hash(fx.dir + L"\\experts.bin", fx.comp, (int64_t)fx.comp.bin_bytes - 4096); // 잘림(reference_lock은 정상)
        int rc = fx.seal((uint64_t)8 * fx.comp.slot_stride_max, 64);
        check(rc < 0, "B5. experts.bin 실크기 불일치 → seal 실패(fail-closed)");
    }
}

// ===========================================================================
// 케이스 C: LRU + lease (층 간 축출·재적재)  [v1 승계]
// ===========================================================================
static void test_lru_lease() {
    section("C. LRU + lease — 슬롯=n_expert, 층 간 축출·재적재 데이터 정합");
    Fixture fx; fx.dir = make_case_dir("lru");
    fx.model.n_expert = 8; fx.model.n_expert_used = 2; fx.model.n_layer = 2;
    fx.model.sources = { default_source() };
    fx.model.layers = { make_separate_layer(0, 8, "MXFP4", false), make_separate_layer(1, 8, "MXFP4", false) };
    fx.comp = compute_layout(fx.model, 4096);
    fx.build();
    int rc = fx.seal((uint64_t)8 * fx.comp.slot_stride_max, 64); // 정확히 8슬롯
    if (!check(rc == 0, "C1. seal 성공(8슬롯=n_expert 8)")) return;

    ggml_tensor * g0 = fx.find("blk.0.ffn_gate_exps.weight");
    ggml_tensor * g1 = fx.find("blk.1.ffn_gate_exps.weight");
    // 층0 전 expert acquire+release(레코드 8개 적재)
    for (int32_t e = 0; e < 8; e++) { int32_t id = e; ggml_moe_direct_acquire(g0, &id, 1, 1); ggml_moe_direct_release(g0, &id, 1); }
    // 층1 전 expert acquire → 층0 슬롯 축출(LRU) → 데이터 정합
    bool ok1 = true;
    for (int32_t e = 0; e < 8; e++) { int32_t id = e; ggml_moe_direct_acquire(g1, &id, 1, 1);
        ok1 = ok1 && verify_ptr_bytes(fx, "blk.1.ffn_gate_exps.weight", 1, 0, e); ggml_moe_direct_release(g1, &id, 1); }
    check(ok1, "C2. ★층1 acquire가 층0 슬롯을 축출 후 재적재·데이터 정합");
    // 층0 재-acquire → MISS 재적재 → 정합
    int32_t id0 = 0; ggml_moe_direct_acquire(g0, &id0, 1, 1);
    check(verify_ptr_bytes(fx, "blk.0.ffn_gate_exps.weight", 0, 0, 0), "C3. 축출된 층0 레코드 재적재 후 정합");
    ggml_moe_direct_release(g0, &id0, 1);
}

