// 케이스 D: mapped-view VirtualProtect 왕복  [v1 승계]
// ===========================================================================
static void test_mapped_view_roundtrip() {
    section("D. mapped-view VirtualProtect(PAGE_NOACCESS↔READONLY) 왕복 + VEH 귀속");
    Fixture fx; fx.dir = make_case_dir("roundtrip");
    fx.model.n_expert = 8; fx.model.n_expert_used = 2; fx.model.n_layer = 1;
    fx.model.sources = { default_source() };
    fx.model.layers = { make_separate_layer(0, 8, "MXFP4", false) };
    fx.comp = compute_layout(fx.model, 4096);
    fx.build();
    int rc = fx.seal((uint64_t)8 * fx.comp.slot_stride_max, 64);
    if (!check(rc == 0, "D1. seal 성공(VEH 등록)")) return;

    // 실 FILE_MAP_READ 뷰 생성(paging file 백업 16KB)
    HANDLE hmap = CreateFileMappingW(INVALID_HANDLE_VALUE, nullptr, PAGE_READWRITE, 0, 16384, nullptr);
    if (!check(hmap != nullptr, "D2. CreateFileMapping 성공")) return;
    void * view = MapViewOfFile(hmap, FILE_MAP_READ, 0, 0, 16384);
    if (!check(view != nullptr, "D3. MapViewOfFile(FILE_MAP_READ) 성공")) { CloseHandle(hmap); return; }
    int r = ggml_moe_direct_test_mapped_view_roundtrip(view, 16384);
    check(r == 0, "D4. ★PAGE_NOACCESS→의도 터치→VEH 카운터+귀속→READONLY 복원→재접근 성공 왕복");
    UnmapViewOfFile(view); CloseHandle(hmap);
}

// ===========================================================================
// 케이스 E: H2D emit 패딩 zero-fill parity  [v1 승계]
// ===========================================================================
struct EmitCollector { std::vector<uint8_t> * dst; };
static void emit_into_buffer(void * ud, const void * src, uint64_t dst_offset, uint64_t len) {
    EmitCollector * c = (EmitCollector *)ud;
    static const uint8_t zero_pad[512] = {0};
    const uint8_t * s = src ? (const uint8_t *)src : zero_pad;
    if (dst_offset + len <= c->dst->size()) std::memcpy(c->dst->data() + dst_offset, s, (size_t)len);
}
static void run_emit_case(Fixture & fx, const std::string & tname, int32_t mlpos, int32_t part_idx, const std::vector<int32_t> & used) {
    ggml_tensor * t = fx.find(tname);
    const CompLayer & cl = fx.comp.layers[(size_t)mlpos];
    uint64_t expert_size = cl.parts[(size_t)part_idx].part_bytes;
    int32_t n_expert = fx.model.n_expert;
    uint64_t total_bytes = (uint64_t)n_expert * expert_size;
    std::vector<int32_t> ids = used; std::sort(ids.begin(), ids.end());
    ggml_moe_direct_acquire(t, ids.data(), (int32_t)ids.size(), 1);
    std::vector<uint8_t> dst((size_t)total_bytes, 0xAA);
    EmitCollector col{ &dst };
    int erc = ggml_moe_direct_emit_expert_copies(t, expert_size, total_bytes, n_expert, ids.data(), (int32_t)ids.size(), emit_into_buffer, &col);
    bool ok = (erc == 0);
    std::vector<uint8_t> covered((size_t)total_bytes, 0);
    for (int32_t e : ids) {
        uint64_t record_off = cl.record_base + (uint64_t)e * cl.stride;
        for (uint64_t i = 0; i < expert_size; i++) {
            covered[(size_t)(e * expert_size + i)] = 1;
            if (dst[(size_t)(e * expert_size + i)] != bin_hash(record_off + cl.parts[(size_t)part_idx].part_offset + i)) ok = false;
        }
    }
    for (size_t k = 0; k < ids.size(); k++) {
        int32_t e = ids[k]; bool boundary = (k + 1 == ids.size()) || (ids[k + 1] != e + 1);
        if (!boundary) continue;
        uint64_t slab_end = (uint64_t)e * expert_size + expert_size;
        uint64_t remaining = slab_end < total_bytes ? total_bytes - slab_end : 0;
        uint64_t zlen = remaining < 512 ? remaining : 512;
        for (uint64_t i = 0; i < zlen; i++) { covered[(size_t)(slab_end + i)] = 1; if (dst[(size_t)(slab_end + i)] != 0) ok = false; }
    }
    for (uint64_t i = 0; i < total_bytes; i++) if (!covered[(size_t)i] && dst[(size_t)i] != 0xAA) ok = false;
    check(ok, "E: emit parity [" + tname + "] used=" + std::to_string(ids.size()) + " (슬랩 정확+경계 zero-fill+미사용 0xAA)");
    ggml_moe_direct_release(t, ids.data(), (int32_t)ids.size());
}
static void test_h2d_emit_parity() {
    section("E. H2D emit_expert_copies 패딩 zero-fill parity(dst 0xAA 센티널)");
    Fixture fx; fx.dir = make_case_dir("emit");
    fx.model.n_expert = 8; fx.model.n_expert_used = 4; fx.model.n_layer = 1;
    fx.model.sources = { default_source() };
    // ne0=256 Q4_K weight, mid=4 → expert_size=144*4=576B(>=512 — 경계 zero-fill 512가 다음
    // 슬랩과 겹치지 않아 검증이 결정적. 실 프로덕션도 expert_size≫512라 겹침 없음).
    SynthLayer L; L.layer = 0;
    SynthPart w; w.name = "gate.weight"; w.source_tensor = "blk.0.ffn_gate_exps.weight"; w.source_index = 0; w.type = "Q4_K"; w.dims = { 256, 4, 8 }; w.is_host = true;
    L.parts = { w };
    fx.model.layers = { L };
    fx.comp = compute_layout(fx.model, 4096);
    fx.build();
    int rc = fx.seal((uint64_t)8 * fx.comp.slot_stride_max, 64);
    if (!check(rc == 0, "E1. seal 성공")) return;
    run_emit_case(fx, "blk.0.ffn_gate_exps.weight", 0, 0, {3, 4, 5});
    run_emit_case(fx, "blk.0.ffn_gate_exps.weight", 0, 0, {0, 7});
    run_emit_case(fx, "blk.0.ffn_gate_exps.weight", 0, 0, {7});
    run_emit_case(fx, "blk.0.ffn_gate_exps.weight", 0, 0, {0, 1, 2, 4, 6, 7});
}

// ===========================================================================
// 설계 §5 소비자 selftest 8종 (④⑤⑥⑦⑧ = 이 프로세스, ①②③ = trace-on 자식)
// ===========================================================================
static void case4_384E_trace_off() {
    // ④ 384E trace-off 정상 — ID 383 실행사 + 단일 커널 고유 demand 129·384 케이스(release 배열 경계)
    Fixture fx; fx.dir = make_case_dir("c4_384E");
    fx.model.arch = "synth384"; fx.model.n_expert = 384; fx.model.n_expert_used = 8; fx.model.n_layer = 2;
    fx.model.sources = { default_source() };
    fx.model.layers = { make_separate_layer(0, 384, "MXFP4", false), make_separate_layer(1, 384, "MXFP4", false) };
    fx.comp = compute_layout(fx.model, 4096);
    fx.build();
    int rc = fx.seal((uint64_t)384 * fx.comp.slot_stride_max, 64); // 384슬롯>=384
    if (!check(rc == 0, "①④-a. 384E seal 성공(trace-off)")) return;
    ggml_tensor * g0 = fx.find("blk.0.ffn_gate_exps.weight");

    // ID 383 실행사
    { int32_t id = 383; int arc = ggml_moe_direct_acquire(g0, &id, 1, 1);
      check(arc == 0 && verify_ptr_bytes(fx, "blk.0.ffn_gate_exps.weight", 0, 0, 383), "④-b. ★ID 383 acquire+ptr 정합(uint16 경계)");
      ggml_moe_direct_release(g0, &id, 1); }

    // 단일 커널 고유 demand 129개(>128 — 구 128 고정 배열 경계 초과)
    { std::vector<int32_t> ids; for (int i = 0; i < 129; i++) ids.push_back(i);
      int arc = ggml_moe_direct_acquire(g0, ids.data(), 129, 8);
      bool ok = (arc == 0) && verify_ptr_bytes(fx, "blk.0.ffn_gate_exps.weight", 0, 0, 128);
      check(ok, "④-c. ★고유 demand 129개 acquire(구 128 배열 경계 초과)+release");
      ggml_moe_direct_release(g0, ids.data(), 129); }

    // 단일 커널 고유 demand 384개(전 expert)
    { std::vector<int32_t> ids; for (int i = 0; i < 384; i++) ids.push_back(i);
      int arc = ggml_moe_direct_acquire(g0, ids.data(), 384, 8);
      bool ok = (arc == 0) && verify_ptr_bytes(fx, "blk.0.ffn_gate_exps.weight", 0, 0, 200) &&
                verify_ptr_bytes(fx, "blk.0.ffn_gate_exps.weight", 0, 0, 383);
      check(ok, "④-d. ★고유 demand 384개 acquire(release 배열 경계 전건)+release");
      ggml_moe_direct_release(fx.find("blk.0.ffn_gate_exps.weight"), ids.data(), 384); }
}
static void case5_K26_shape() {
    // ⑤ 384E + separate 3w/no-bias + leading-dense(K2.6 형상) — moe_layers 0시작 아님
    Fixture fx; fx.dir = make_case_dir("c5_k26");
    fx.model.arch = "deepseek2"; fx.model.n_expert = 384; fx.model.n_expert_used = 8; fx.model.n_layer = 4;
    fx.model.sources = { default_source() };
    // leading dense: layer 0 은 dense(비 moe) — moe_layers = {1,2,3}
    fx.model.layers = { make_separate_layer(1, 384, "MXFP4", false),
                        make_separate_layer(2, 384, "MXFP4", false),
                        make_separate_layer(3, 384, "MXFP4", false) };
    fx.comp = compute_layout(fx.model, 4096);
    fx.build();
    int rc = fx.seal((uint64_t)384 * fx.comp.slot_stride_max, 64);
    if (!check(rc == 0, "⑤-a. K2.6 형상 seal 성공(384E·separate 3w·no-bias·leading-dense moe_layers={1,2,3})")) return;
    // mlpos 0 == layer 1
    ggml_tensor * g1 = fx.find("blk.1.ffn_gate_exps.weight");
    ggml_tensor * d3 = fx.find("blk.3.ffn_down_exps.weight");
    int32_t id = 383; ggml_moe_direct_acquire(g1, &id, 1, 1);
    bool ok = verify_ptr_bytes(fx, "blk.1.ffn_gate_exps.weight", 0, 0, 383);
    ggml_moe_direct_release(g1, &id, 1);
    ggml_moe_direct_acquire(d3, &id, 1, 1);
    ok = ok && verify_ptr_bytes(fx, "blk.3.ffn_down_exps.weight", 2, 2, 383); // mlpos 2 = layer 3, part 2 = down
    ggml_moe_direct_release(d3, &id, 1);
    int lp_layer = -1, lp_part = -1; ggml_moe_direct_registered_layer_part(g1, &lp_layer, &lp_part);
    check(ok && lp_layer == 1 && lp_part == 0, "⑤-b. ★leading-dense mlpos↔실제 layer 매핑·ptr 정합(layer1 part0)");
}
static void case6_mistral_shape() {
    // ⑥ fused 2-part/no-bias + 층별 Q4/Q6(Mistral 형상 — 층별 stride 상이)
    Fixture fx; fx.dir = make_case_dir("c6_mistral");
    fx.model.arch = "mistral4"; fx.model.n_expert = 128; fx.model.n_expert_used = 4; fx.model.n_layer = 2;
    fx.model.sources = { default_source() };
    // layer0 Q4_K(mid=2 → slice 288, payload 576 → stride 4096)
    // layer1 Q6_K(mid=16 → slice 3360, payload 6720 → stride 8192) — 층별 stride 상이
    fx.model.layers = { make_fused_layer(0, 128, "Q4_K", 2), make_fused_layer(1, 128, "Q6_K", 16) };
    fx.comp = compute_layout(fx.model, 4096);
    fx.build();
    bool stride_diff = fx.comp.layers[0].stride != fx.comp.layers[1].stride;
    check(stride_diff, "⑥-a. 층별 stride 상이 확인(layer0=" + std::to_string(fx.comp.layers[0].stride) + " layer1=" + std::to_string(fx.comp.layers[1].stride) + ")");
    int rc = fx.seal((uint64_t)128 * fx.comp.slot_stride_max, 64);
    if (!check(rc == 0, "⑥-b. Mistral 형상 seal 성공(fused 2-part·no-bias·층별 Q4/Q6)")) return;
    // layer1(큰 stride) down.weight(part1) 정합 — 층별 stride/record_base 산술 행사
    ggml_tensor * d1 = fx.find("blk.1.ffn_down_exps.weight");
    int32_t id = 100; ggml_moe_direct_acquire(d1, &id, 1, 8);
    bool ok = verify_ptr_bytes(fx, "blk.1.ffn_down_exps.weight", 1, 1, 100);
    ggml_moe_direct_release(d1, &id, 1);
    ggml_tensor * gu0 = fx.find("blk.0.ffn_gate_up_exps.weight");
    ggml_moe_direct_acquire(gu0, &id, 1, 8);
    ok = ok && verify_ptr_bytes(fx, "blk.0.ffn_gate_up_exps.weight", 0, 0, 100);
    ggml_moe_direct_release(gu0, &id, 1);
    check(ok, "⑥-c. ★층별 stride/record_base로 fused 2-part 각 층 ptr 정합");
}
